parameters.jsonBody:
={
  "model": "gemini-decision-1",
  "input": {{ JSON.stringify("From: " + ($json.sender ?? '') + "\nSubject: " + ($json.subject ?? '') + "\n\n" + ($json.bodyStart ?? '').slice(0, 500)) }},
  "questions": {
    "category": {
      "type": "choice",
      "instructions": "You are sorting a personal inbox. Which category best fits this email?",
      "criteria": {
        "subscriptions": "Newsletters and content the user signed up for: blogs, media, YouTube, Substack. No payment involved.",
        "invoices": "Invoices, receipts and direct debits, including those of subscription services. As soon as an amount is paid, it is an invoice.",
        "jobs": "Replies to job applications, recruiters, interview invitations and job alerts (LinkedIn, Indeed, Welcome to the Jungle).",
        "admin": "Bank, taxes, family allowance (CAF), social security, health insurance, insurance, town hall.",
        "orders": "Order confirmations, parcel tracking and returns.",
        "personal": "Emails written by real people (family, friends), outside work.",
        "security": "Verification codes, login alerts and password resets.",
        "trash": "Ads, promotions, cold sales pitches and unsolicited marketing.",
        "other": "Anything that clearly fits none of the other categories."
      }
    }
  }
}
